const raw =
  $json.output?.[0]?.content?.[0]?.text;

if (!raw) {
  return {
    json: {
      menus: [],
      error: "EMPTY_OPENAI_RESPONSE",
      message: "OpenAI 응답이 비어 있습니다.",
    },
  };
}

const cleaned = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch {
  return {
    json: {
      menus: [],
      error: "INVALID_JSON",
      message:
        "OpenAI 응답을 JSON으로 변환하지 못했습니다.",
      raw: cleaned,
    },
  };
}

const sourceMenus = Array.isArray(parsed.menus)
  ? parsed.menus
  : [];

const menus = sourceMenus
  .map((menu, index) => {
    const box =
      menu.box ??
      menu.boundingBox ??
      menu.bounding_box ??
      {};

    const menuName =
      menu.menuName ??
      menu.menu_name ??
      menu.name ??
      "";

    const price = Number(
      String(menu.price ?? "").replace(
        /[^0-9]/g,
        "",
      ),
    );

    const x = Number(
      box.x ?? box.left ?? box.xmin ?? 0,
    );

    const y = Number(
      box.y ?? box.top ?? box.ymin ?? 0,
    );

    let width = Number(box.width ?? 0);
    let height = Number(box.height ?? 0);

    if (
      !width &&
      box.xmax !== undefined
    ) {
      width = Number(box.xmax) - x;
    }

    if (
      !height &&
      box.ymax !== undefined
    ) {
      height = Number(box.ymax) - y;
    }

    return {
      id:
        menu.id ||
        `menu-${index + 1}`,
      section: menu.section || "",
      menuName,
      price,
      box: {
        x,
        y,
        width,
        height,
      },
    };
  })
  .filter(
    (menu) =>
      menu.menuName &&
      menu.price > 0 &&
      menu.box.width > 0 &&
      menu.box.height > 0,
  );

return {
  json: {
    detectedMenuCount: menus.length,
    menus,
  },
};

const raw =
  $json.text ??
  $json.output?.[0]?.content?.[0]?.text ??
  $json.content;

if (!raw) {
  return {
    json: {
      error: "EMPTY_OPENAI_RESPONSE",
      message: "OpenAI 상세정보 응답이 비어 있습니다.",
    },
  };
}

const cleaned = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

try {
  return {
    json: JSON.parse(cleaned),
  };
} catch {
  return {
    json: {
      error: "INVALID_JSON",
      message: "상세정보 응답을 JSON으로 변환하지 못했습니다.",
      raw: cleaned,
    },
  };
}

