const raw =
  $json.text ??
  $json.output?.[0]?.content?.[0]?.text ??
  $json.content ??
  $json.response;

if (!raw) {
  throw new Error("AI response is empty.");
}

if (typeof raw === "object") {
  return {
    json: raw,
  };
}

const cleaned = raw
  .replace(/^```json/i, "")
  .replace(/^```/, "")
  .replace(/```$/, "")
  .trim();

const parsed = JSON.parse(cleaned);

return {
  json: parsed,
};
